#!/usr/bin/env python3
import bz2
import gzip
import os
import sys
import zlib
import unix_compress

VERSION = """Ancient v2.3.0
Copyright (C) Teemu Suutari

Usage: ancient i[dentify] packed_input_files...
 - identifies compression used in a file(s)
Usage: ancient v[erify] packed_input_file unpacked_comparison_file
 - verifies decompression against known good unpacked file
Usage: ancient [-p] d[ecompress] packed_input_file output_file
 - decompresses single file
 - use p-flag to preserve timestamp of the original"""


def fail(s):
    print(s, file=sys.stderr)
    return 255


class DecompressionFailed(Exception):
    pass


class GzipRawFailed(Exception):
    pass


class BzipRawFailed(Exception):
    def __init__(self, output, checksum_only=False):
        self.output = output
        self.checksum_only = checksum_only


def bzip_combined_crc(data):
    marker = int.from_bytes(b"\x17\x72\x45\x38\x50\x90", "big")
    packed = int.from_bytes(data, "big")
    total_bits = len(data) * 8
    for pos in range(32, max(32, total_bits - 79)):
        tail = total_bits - pos - 48
        if 32 <= tail <= 39 and ((packed >> tail) & ((1 << 48) - 1)) == marker:
            return (packed >> (tail - 32)) & 0xffffffff
    raise ValueError


def bzip_crc(data):
    table = []
    for n in range(256):
        value = n << 24
        for _ in range(8):
            value = (((value << 1) ^ 0x04c11db7) if value & 0x80000000 else value << 1) & 0xffffffff
        table.append(value)
    value = 0xffffffff
    for byte in data:
        value = ((value << 8) & 0xffffffff) ^ table[((value >> 24) ^ byte) & 255]
    return value ^ 0xffffffff


def has_bzip_end_marker(data):
    marker = int.from_bytes(b"\x17\x72\x45\x38\x50\x90", "big")
    total_bits = len(data) * 8
    packed = int.from_bytes(data, "big")
    for pos in range(32, max(32, total_bits - 79)):
        tail = total_bits - pos - 48
        if 32 <= tail <= 39 and ((packed >> tail) & ((1 << 48) - 1)) == marker:
            return True
    return False


def recover_bzip_crc(data, partial):
    block = b"\x31\x41\x59\x26\x53\x59"
    try:
        combined_crc = bzip_combined_crc(data)
    except ValueError:
        return None
    if data.count(block) != 1:
        return None
    crc_pos = data.find(block) + 6
    candidates = [partial]
    candidates.extend(partial + bytes((byte,)) for byte in range(256))
    for candidate in candidates:
        candidate_crc = bzip_crc(candidate)
        if candidate_crc != combined_crc:
            continue
        crc = candidate_crc.to_bytes(4, "big")
        fixed = bytearray(data)
        fixed[crc_pos:crc_pos + 4] = crc
        try:
            return bz2.decompress(fixed)
        except Exception:
            pass
    return None


STONECRACKER_IDS = {
    b"S310": "S310: StoneCracker v3.10, v3.11b",
    b"S400": "S400: StoneCracker pre v4.00",
    b"S401": "S401: StoneCracker v4.01",
    b"S403": "S403: StoneCracker v4.02a",
    b"S404": "S404: StoneCracker v4.10",
    b"2AM": "S401: StoneCracker v4.01",
    b"AYS!": "S404: StoneCracker v4.10",
    b"Z&G!": "S403: StoneCracker v4.02a",
    b"ZULU": "S403: StoneCracker v4.02a",
}
STONECRACKER_MIN_LENGTH = {
    b"S403": 18, b"S404": 18, b"AYS!": 18,
    b"Z&G!": 18, b"ZULU": 18,
}


def gzip_body(data, offset):
    if len(data) < offset + 10 or data[offset:offset + 2] != b"\x1f\x8b":
        raise ValueError()
    if data[offset + 2] != 8 or data[offset + 3] & 0xe0:
        raise ValueError()
    flags = data[offset + 3]
    pos = offset + 10
    if flags & 4:
        if pos + 2 > len(data):
            raise ValueError()
        size = int.from_bytes(data[pos:pos + 2], "little")
        pos += 2 + size
    for bit in (8, 16):
        if flags & bit:
            end = data.find(b"\0", pos)
            if end < 0:
                raise ValueError()
            pos = end + 1
    if flags & 2:
        pos += 2
    if pos > len(data):
        raise ValueError()
    dec = zlib.decompressobj(-15)
    try:
        out = dec.decompress(data[pos:])
    except zlib.error as e:
        raise ValueError() from e
    if not dec.eof:
        raise ValueError()
    return out, data[pos + len(data[pos:]) - len(dec.unused_data):]


def gzip_incomplete_stable(data):
    if len(data) < 10 or data[:2] != b"\x1f\x8b" or data[2] != 8 or data[3] & 0xe0:
        return False
    flags, pos = data[3], 10
    if flags & 4:
        if pos + 2 > len(data):
            return False
        pos += 2 + int.from_bytes(data[pos:pos + 2], "little")
    for bit in (8, 16):
        if flags & bit:
            end = data.find(b"\0", pos)
            if end < 0:
                return False
            pos = end + 1
    if flags & 2:
        pos += 2
    raw = data[pos:]
    if not raw:
        return False
    try:
        original = zlib.decompressobj(-15).decompress(raw)
    except zlib.error:
        return False
    for pad in range(1, 9):
        decoder = zlib.decompressobj(-15)
        try:
            result = decoder.decompress(raw + b"\0" * pad)
        except zlib.error:
            continue
        if decoder.eof:
            return result == original
    return False


def gzip_identifies(data):
    remaining = data
    any_output = False
    while remaining:
        try:
            member, trailer = gzip_body(remaining, 0)
        except ValueError:
