        label = "Z: Compress (new)" if len(data) > 2 and data[2] & 0x80 else "Z: Compress (old)"
        return label, unix_compress.decompress(data)
    raise ValueError


def verify_bzip_block_crc(src, expected):
    # Recover a single block whose data and combined stream CRC are intact,
    # but whose block CRC field was damaged.
    if (len(src) < 14 or not src.startswith(b"BZh") or src[4:10] != b"1AY&SY"
