        raise ValueError
    fixed = bytearray(src)
    fixed[10:14] = bzip_crc(expected).to_bytes(4, "big")
    return bz2.decompress(fixed)


def main(argv):
    preserve = False
    if argv and argv[0] == "-p":
        preserve = True
        argv = argv[1:]
    if not argv:
        print(VERSION, file=sys.stderr)
        return 255
    cmd = argv[0]
