def gzip_incomplete_stable(data):
    if len(data) < 10 or data[:2] != b"\x1f\x8b" or data[2] != 8 or data[3] & 0xe0:
        return False
    flags, pos = data[3], 10
    if flags & 4:
        if pos + 2 > len(data):
            return False
        pos += 2 + int.from_bytes(data[pos:pos + 2], "little")
    for bit in (8, 16):
        if flags & bit:
            end = data.find(b"\0", pos)
            if end < 0:
                return False
            pos = end + 1
    if flags & 2:
        pos += 2
    raw = data[pos:]
    if not raw:
        return False
    try:
        original = zlib.decompressobj(-15).decompress(raw)
    except zlib.error:
        return False
    for pad in range(1, 9):
        decoder = zlib.decompressobj(-15)
        try:
            result = decoder.decompress(raw + b"\0" * pad)
        except zlib.error:
            continue
        if decoder.eof:
            return result == original
    return False


def gzip_identifies(data):
    remaining = data
    last_output = False
    while remaining:
        try:
            member, trailer = gzip_body(remaining, 0)
        except ValueError:
            return gzip_incomplete_stable(remaining)
        last_output = bool(member)
        if 0 < len(trailer) < 6:
            return False
        if len(trailer) < 8:
            return last_output and len(trailer) in (0, 6, 7)
        remaining = trailer[8:]
    return last_output


def gzip_raw(data):
    result, trailer = gzip_body(data, 0)
    return result, len(data) - len(trailer)


